1	// Local counterpart of the ADR half of require-status-matches-coverage:
2	// an ADR must declare a lifecycle status the parsers can read, while staying
3	// exempt from the coverage tier that rule would also demand of it. Specs are
4	// gated in eslint.config.mjs by re-lint/require-intro-paragraph and
5	// re-lint/require-status-matches-coverage; the statement-link report behind
6	// --coverage is never a gate (AGENTS.md § Spec Header Table).
7	
8	import { readFileSync, readdirSync } from "node:fs";
9	import { join, relative, resolve } from "node:path";
10	import process from "node:process";
11	import { parseDocStatus } from "@re-cinq/eslint-plugin-re-lint/spec/spec-status.js";
12	import { unlinkedTestableStatements } from "@re-cinq/eslint-plugin-re-lint/spec/spec-status-coverage.js";
13	import { root } from "./lib/repo-root.mjs";
14	
15	const USAGE =
16	  "usage: check-spec-status.mjs [--coverage] [--json] [doc-path ...]\n" +
17	  "doc paths resolve against the repo root, not the working directory; an absolute path is taken as given";
18	
19	const args = process.argv.slice(2);
20	const flags = args.filter((arg) => arg.startsWith("--"));
21	const docArgs = args.filter((arg) => !arg.startsWith("--"));
22	
23	const usageExit = () => {
24	  process.stderr.write(`${USAGE}\n`);
25	  process.exit(2);
26	};
27	
28	for (const flag of flags) {
29	  if (flag === "--json" || flag === "--coverage") {
30	    continue;
31	  }
32	  usageExit();
33	}
34	
35	const asJson = flags.includes("--json");
36	const asCoverage = flags.includes("--coverage");
37	
38	const markdownIn = (dir) =>
39	  readdirSync(join(root, dir), { withFileTypes: true })
40	    .filter((entry) => entry.isFile() && entry.name.endsWith(".md"))
41	    .map((entry) => `${dir}/${entry.name}`)
42	    .sort();
43	
44	const specDocs = () =>
45	  readdirSync(join(root, "specs"), { withFileTypes: true })
46	    .filter((entry) => entry.isDirectory())
47	    .map((entry) => `specs/${entry.name}/spec.md`)
48	    .sort();
49	
50	const discoverDocs = () => [...specDocs(), ...markdownIn("adrs")];
51	
52	const docPaths =
53	  docArgs.length > 0 ? docArgs.map((path) => relative(root, resolve(root, path))) : discoverDocs();
54	
55	const readDoc = (docPath) => {
56	  try {
57	    return readFileSync(join(root, docPath), "utf8");
58	  } catch (error) {
59	    process.stderr.write(`cannot read doc ${docPath}: ${error.message}\n`);
60	    process.exit(2);
61	  }
62	};
63	
64	// The corpus folders the rules assume by default, matched at any depth so fixtures qualify.
65	const docKind = (docPath) => {
66	  if (/(^|\/)specs\//.test(docPath)) {
67	    return "spec";
68	  }
69	
70	  return /(^|\/)adrs\//.test(docPath) ? "adr" : null;
71	};
72	
73	// The frontmatter line a human has to edit, or the top of the file when there is none.
74	const frontmatterStatusLine = (content) => {
75	  const index = content.split(/\r?\n/).findIndex((line) => /^status\s*:/i.test(line));
76	
77	  return index === -1 ? 1 : index + 1;
78	};
79	
80	const adrStatusFindings = (docPath, content) => {
81	  if (parseDocStatus(content, "adr").status !== null) {
82	    return [];
83	  }
84	
85	  return [
86	    {
87	      doc: docPath,
88	      line: frontmatterStatusLine(content),
89	      kind: "untagged",
90	      message: "no lifecycle status the parsers can read",
91	    },
92	  ];
93	};
94	
95	const EXCERPT = 80;
96	
97	const coverageFindings = (docPath, content) =>
98	  unlinkedTestableStatements(content).map((statement) => ({
99	    doc: docPath,
100	    line: statement.line,
101	    kind: "unlinked",
102	    message: `unlinked testable statement: ${statement.text
103	      .replace(/\s+/g, " ")
104	      .trim()
105	      .slice(0, EXCERPT)}`,
106	  }));
107	
108	const findingsFor = (docPath, content, kind) => {
109	  if (asCoverage) {
110	    return coverageFindings(docPath, content);
111	  }
112	
113	  return kind === "adr" ? adrStatusFindings(docPath, content) : [];
114	};
115	
116	const findings = [];
117	const docsWithFindings = new Set();
