1	// Vendored verbatim from re-cinq/lore libs/shared/src (commit 4536b6c6f). Lore stays the source of truth; keep in sync.
2	/** Deterministic spec segmentation; must agree with rehype highlighter on (ordinal, text, kind). */
3	import { splitSentences } from "./spec-sentence-split.js";
4	function isListItem(line) {
5	    return /^\s*(?:[-*+]\s+|\d+\.\s+)/.test(line);
6	}
7	function stripListMarker(line) {
8	    return line.replace(/^\s*(?:[-*+]\s+|\d+\.\s+)/, "").trim();
9	}
10	function isHeading(line) {
11	    return /^#{1,6}\s+\S/.test(line);
12	}
13	function parseHeading(line) {
14	    return line.replace(/^#{1,6}\s+/, "").trim();
15	}
16	function isTableRow(line) {
17	    const t = line.trim();
18	    return t.startsWith("|") && t.endsWith("|") && t.length >= 2;
19	}
20	function endsListItem(line) {
21	    if (line.trim() === "" || isListItem(line)) {
22	        return true;
23	    }
24	    if (isHeading(line) || isTableRow(line)) {
25	        return true;
26	    }
27	    return /^\s*```/.test(line);
28	}
29	function readListItemLines(lines, startIndex) {
30	    let combined = stripListMarker(lines[startIndex]);
31	    let index = startIndex;
32	    while (index + 1 < lines.length && !endsListItem(lines[index + 1])) {
33	        combined += " " + lines[index + 1].trim();
34	        index++;
35	    }
36	    return { combined: combined.replace(/\s+/g, " ").trim(), endIndex: index };
37	}
38	/** Classifies a non-fence, non-blank-checked line by which segmentation action it triggers. */
39	function classifyStatementLine(line) {
40	    if (line.trim() === "") {
41	        return "blank";
42	    }
43	    if (isHeading(line)) {
44	        return "heading";
45	    }
46	    if (isTableRow(line)) {
47	        return "table";
48	    }
49	    if (isListItem(line)) {
50	        return "list-item";
51	    }
52	    return "paragraph";
53	}
54	/** Line-by-line statement accumulator behind `segmentStatements`. */
55	class StatementAccumulator {
56	    statements = [];
57	    ordinal = 0;
58	    currentHeading = null;
59	    inFence = false;
60	    paragraphLines = [];
61	    paragraphStartLine = 0;
62	    flushParagraph() {
63	        if (this.paragraphLines.length === 0) {
64	            return;
65	        }
66	        const para = this.paragraphLines.join(" ");
67	        const startLine = this.paragraphStartLine;
68	        this.paragraphLines = [];
69	        for (const sentence of splitSentences(para)) {
70	            this.statements.push({
71	                ordinal: this.ordinal++,
72	                text: sentence,
73	                kind: "sentence",
74	                enclosingHeading: this.currentHeading,
75	                line: startLine,
76	            });
77	        }
78	    }
79	    pushListItemStatement(text, line) {
80	        if (!text) {
81	            return;
82	        }
83	        this.statements.push({
84	            ordinal: this.ordinal++,
85	            text,
86	            kind: "list-item",
87	            enclosingHeading: this.currentHeading,
88	            line,
89	        });
90	    }
91	    appendParagraphLine(line, lineNumber) {
92	        if (this.paragraphLines.length === 0) {
93	            this.paragraphStartLine = lineNumber;
94	        }
95	        this.paragraphLines.push(line.trim());
96	    }
97	    actionHandlers = {
98	        blank: (_lines, i) => {
99	            this.flushParagraph();
100	            return i;
101	        },
102	        heading: (_lines, i, line) => {
103	            this.flushParagraph();
104	            this.currentHeading = parseHeading(line);
105	            return i;
106	        },
107	        table: (_lines, i) => {
108	            this.flushParagraph();
109	            return i;
110	        },
111	        "list-item": (lines, i) => {
112	            this.flushParagraph();
113	            const itemStartLine = i + 1;
114	            const listItem = readListItemLines(lines, i);
115	            this.pushListItemStatement(listItem.combined, itemStartLine);
